export const DEFAULT_PRESET='aquazone:1';
const cache=new Map();
export function presetById(id){
 const bank=banks.find(b=>b.presets.some(p=>p.id===id));
 if(!bank)return null;
 if(!cache.has(bank.id)){const bytes=Uint8Array.from(atob(bank.data),c=>c.charCodeAt(0));cache.set(bank.id,parseSyxBank(bytes));}
 return cache.get(bank.id)[bank.presets.find(p=>p.id===id).slot];
}
